/**
 * Sub-issue tree rules.
 *
 * An issue may sit under a parent issue of its own project. The tree never
 * loops and never grows deeper than `MAX_SUB_ISSUE_DEPTH` (a root issue is at
 * level 0). A violation is raised as `IssueHierarchyError`, which
 * `toAppError()` maps to `conflict`.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export type IssueHierarchyViolation = "cycle" | "too_deep";

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyViolation,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH} levels of sub-issues.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * Throws unless a subtree of `subtreeHeight` levels below its root can be
 * hung under a parent at `parentLevel`. The subtree root lands one level
 * below the parent; its deepest descendant `subtreeHeight` levels further.
 */
export function assertDepthAllowed(
  issueId: string,
  parentLevel: number,
  subtreeHeight: number,
): void {
  if (parentLevel + 1 + subtreeHeight > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}
