/**
 * Every issue of a project, archived ones included, without labels. The
 * sub-issue tree is walked in memory over this list.
 */
export async function listProjectIssueTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

/** Live direct sub-issues, oldest first (creation time, then number). */
export async function listSubIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Archives the given issues that are still live; returns those archived. */
export async function archiveLiveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

