/** The two fields of an issue the tree is built from. */
export interface IssueTreeNode<Id extends string = string> {
  readonly id: Id;
  readonly parentId: Id | null;
}

/**
 * An in-memory view of one project's sub-issue tree. Walks are guarded
 * against loops already present in stored data, so they always terminate.
 */
export class IssueTree<T extends IssueTreeNode<Id>, Id extends string = string> {
  private readonly byId = new Map<string, T>();
  private readonly childrenOf = new Map<string, T[]>();

  constructor(nodes: readonly T[]) {
    for (const node of nodes) this.byId.set(node.id, node);
    for (const node of nodes) {
      if (node.parentId === null) continue;
      const bucket = this.childrenOf.get(node.parentId) ?? [];
      bucket.push(node);
      this.childrenOf.set(node.parentId, bucket);
    }
  }

  /** Every issue below `id` at any depth, breadth-first, `id` excluded. */
  descendants(id: Id): readonly T[] {
    const seen = new Set<string>([id]);
    const out: T[] = [];
    let frontier: readonly string[] = [id];
    while (frontier.length > 0) {
      const next: string[] = [];
      for (const current of frontier) {
        for (const child of this.childrenOf.get(current) ?? []) {
          if (seen.has(child.id)) continue;
          seen.add(child.id);
          out.push(child);
          next.push(child.id);
        }
      }
      frontier = next;
    }
    return out;
  }

  /** Levels between `id` and its deepest descendant (0 for a leaf). */
  height(id: Id): number {
    const seen = new Set<string>([id]);
    let height = 0;
    let frontier: readonly string[] = [id];
    for (;;) {
      const next: string[] = [];
      for (const current of frontier) {
        for (const child of this.childrenOf.get(current) ?? []) {
          if (seen.has(child.id)) continue;
          seen.add(child.id);
          next.push(child.id);
        }
      }
      if (next.length === 0) return height;
      height += 1;
      frontier = next;
    }
  }

  /** Distance from `id` up to its root issue (0 for a root issue). */
  level(id: Id): number {
    const seen = new Set<string>([id]);
    let level = 0;
    let current = this.byId.get(id);
    while (current !== undefined && current.parentId !== null) {
      if (seen.has(current.parentId)) break;
      seen.add(current.parentId);
      level += 1;
      current = this.byId.get(current.parentId);
    }
    return level;
  }
}
